/**
 * SPEC-060: derivación pura de los 8 pasos del banner de primeros pasos
 * (lib/appOnboarding). Sin DOM: aquí se fijan la tabla del «Modelo de pasos»
 * (literales, condición de completado y destino de cada CTA), el paso actual
 * como primer no completado, el contador que cuenta también los completados
 * fuera de orden y los fallbacks de los destinos con id. La visibilidad
 * (loading/error/hidden) NO se decide aquí sino en el hook, y se cubre por
 * página en CapturesPage.onboarding.test.tsx.
 * Generated by QA Dev agent.
 */
import { describe, expect, it } from 'vitest'
import { deriveAppOnboarding, type AppOnboardingView } from '@/lib/appOnboarding'
import type { AppOnboardingStatus } from '@/types/domain'

/** Instalación nueva: nada persistido, nada creado. */
function status(overrides: Partial<AppOnboardingStatus> = {}): AppOnboardingStatus {
  return {
    settings: { promptsReviewedAt: null, hiddenAt: null },
    hasInterviewTemplate: false,
    hasNoteTemplate: false,
    hasCompany: false,
    hasContact: false,
    hasDiscovery: false,
    hasInterviewGroup: false,
    hasGroupedInterview: false,
    firstCompanyId: null,
    firstDiscoveryId: null,
    firstGroup: null,
    ...overrides
  }
}

function derive(
  overrides: Partial<AppOnboardingStatus> = {},
  keys: { anthropicConfigured?: boolean; deepgramConfigured?: boolean } = {}
): AppOnboardingView {
  return deriveAppOnboarding({
    status: status(overrides),
    anthropicConfigured: keys.anthropicConfigured ?? false,
    deepgramConfigured: keys.deepgramConfigured ?? false
  })
}

/** Estado que completa los 8 pasos (con los ids de destino poblados). */
const ALL_DONE: Partial<AppOnboardingStatus> = {
  settings: { promptsReviewedAt: '2026-07-29T08:00:00.000Z', hiddenAt: null },
  hasInterviewTemplate: true,
  hasNoteTemplate: true,
  hasCompany: true,
  hasContact: true,
  hasDiscovery: true,
  hasInterviewGroup: true,
  hasGroupedInterview: true,
  firstCompanyId: 'c-1',
  firstDiscoveryId: 'd-1',
  firstGroup: { id: 'g-1', discoveryId: 'd-1' }
}

describe('deriveAppOnboarding', () => {
  // SPEC-060 · AC-01 (mitad derivada: paso 1 actual y contador 0)
  it('starts a fresh install with the 8 steps pending, step 1 as current and a 0 count', () => {
    const view = derive()

    expect(view.steps).toHaveLength(8)
    expect(view.steps.map((step) => step.step)).toEqual([1, 2, 3, 4, 5, 6, 7, 8])
    expect(view.steps.every((step) => !step.done)).toBe(true)
    expect(view.doneCount).toBe(0)
    expect(view.currentStep).toBe(1)
  })

  // SPEC-060 · Modelo de pasos (literales normativos de la tabla y de los
  // textos de apoyo: son contrato de la spec, no decoración)
  it('exposes the literal label, support line and CTA of every step', () => {
    const view = derive()

    expect(view.steps.map((step) => step.label)).toEqual([
      'Configura las claves de IA',
      'Revisa los prompts personalizados',
      'Crea las plantillas de preguntas y notas',
      'Crea la primera empresa',
      'Añade el primer contacto',
      'Crea el primer discovery',
      'Crea el primer grupo de entrevistas',
      'Crea la primera entrevista'
    ])
    expect(view.steps.map((step) => step.ctaLabel)).toEqual([
      'Ir a Ajustes',
      'Revisar prompts',
      'Crear plantillas',
      'Crear empresa',
      'Añadir contacto',
      'Crear discovery',
      'Crear grupo',
      'Crear entrevista'
    ])
    expect(view.steps.map((step) => step.support)).toEqual([
      'Maurya necesita la clave de Claude para generar y la de Deepgram para transcribir.',
      'Los prompts definen cómo se comporta la IA; puedes personalizarlos o dejar los de serie.',
      'Las plantillas de preguntas alimentan el guión y las de notas dan forma al resumen.',
      'Las entrevistas se organizan por la empresa a la que entrevistas.',
      'Los contactos son las personas de la empresa que participan en las entrevistas.',
      'Un discovery agrupa todo el trabajo de descubrimiento de un problema.',
      'Los grupos organizan las entrevistas de un discovery y fijan sus plantillas.',
      'Crea la entrevista desde el grupo: hereda su plantilla y sus objetivos.'
    ])
  })

  // SPEC-060 · AC-08 (una sola clave no completa el paso 1)
  it('keeps step 1 pending when only one of the two keys is configured', () => {
    for (const keys of [
      { anthropicConfigured: true, deepgramConfigured: false },
      { anthropicConfigured: false, deepgramConfigured: true }
    ]) {
      const view = derive({}, keys)
      expect(view.steps[0].done).toBe(false)
      expect(view.currentStep).toBe(1)
      expect(view.doneCount).toBe(0)
    }
  })

  // SPEC-060 · AC-09 (ambas claves → paso 1 done y el actual pasa al 2)
  it('completes step 1 with both keys configured and moves the current step to 2', () => {
    const view = derive({}, { anthropicConfigured: true, deepgramConfigured: true })

    expect(view.steps[0].done).toBe(true)
    expect(view.steps[0].target).toBe('/settings?tab=api-keys')
    expect(view.currentStep).toBe(2)
    expect(view.doneCount).toBe(1)
  })

  // SPEC-060 · AC-11 (mitad derivada: la marca persistida completa el paso 2)
  it('completes step 2 from the persisted promptsReviewedAt mark', () => {
    const view = derive({
      settings: { promptsReviewedAt: '2026-07-29T08:00:00.000Z', hiddenAt: null }
    })

    expect(view.steps[1].done).toBe(true)
    expect(view.steps[1].target).toBe('/settings?tab=custom-prompts')
  })

  // SPEC-060 · AC-12 (sin ninguna plantilla el CTA apunta a preguntas primero)
  it('points step 3 at the interview templates tab when no template exists at all', () => {
    const view = derive()

    expect(view.steps[2].done).toBe(false)
    expect(view.steps[2].target).toBe('/settings?tab=interview-templates')
  })

  // SPEC-060 · AC-13 (con las de preguntas cubiertas, el CTA salta a notas)
  it('keeps step 3 pending with only interview templates and retargets it at the note tab', () => {
    const view = derive({ hasInterviewTemplate: true })

    expect(view.steps[2].done).toBe(false)
    expect(view.steps[2].target).toBe('/settings?tab=note-templates')
  })

  // SPEC-060 · AC-14 (las dos familias completan el paso 3)
  it('completes step 3 only with both template families', () => {
    const view = derive({ hasInterviewTemplate: true, hasNoteTemplate: true })

    expect(view.steps[2].done).toBe(true)
  })

  // SPEC-060 · AC-06 (completado fuera de orden: check y suma al contador, sin
  // mover el paso actual)
  it('checks an out-of-order completed step and counts it without moving the current step', () => {
    const view = derive({ hasCompany: true })

    expect(view.steps[3].done).toBe(true)
    expect(view.doneCount).toBe(1)
    expect(view.currentStep).toBe(1)
  })

  // SPEC-060 · AC-16/AC-19/AC-20 (mitad derivada: destinos con id resueltos)
  it('resolves the id-bearing targets of steps 5, 7 and 8 from the aggregate', () => {
    const view = derive({
      firstCompanyId: 'c-1',
      firstDiscoveryId: 'd-1',
      firstGroup: { id: 'g-1', discoveryId: 'd-9' }
    })

    expect(view.steps[4].target).toBe('/companies/c-1')
    expect(view.steps[6].target).toBe('/discoveries/d-1')
    // El grupo navega a SU discovery, no al primero del listado
    expect(view.steps[7].target).toBe('/discoveries/d-9/groups/g-1')
  })

  // SPEC-060 · Notas técnicas: jamás se construye una URL con un id ausente
  it('falls back to the list routes when the aggregate has no ids yet', () => {
    const view = derive()

    expect(view.steps[4].target).toBe('/companies')
    expect(view.steps[6].target).toBe('/discoveries')
    expect(view.steps[7].target).toBe('/discoveries')
    // Los destinos sin id son fijos
    expect(view.steps[3].target).toBe('/companies')
    expect(view.steps[5].target).toBe('/discoveries')
  })

  // SPEC-060 · AC-17/AC-22 (mitad derivada de los pasos 5 y 8)
  it('completes steps 5 and 8 from the contact and grouped-interview flags', () => {
    expect(derive({ hasContact: true }).steps[4].done).toBe(true)
    expect(derive({ hasGroupedInterview: true }).steps[7].done).toBe(true)
    // Un grupo creado no implica entrevista con grupo (paso 8 independiente)
    const withGroup = derive({ hasInterviewGroup: true })
    expect(withGroup.steps[6].done).toBe(true)
    expect(withGroup.steps[7].done).toBe(false)
  })

  // SPEC-060 · AC-05 (mitad derivada: los 8 completados → sin paso actual)
  it('returns a null current step and a full count when the 8 conditions hold', () => {
    const view = derive(ALL_DONE, { anthropicConfigured: true, deepgramConfigured: true })

    expect(view.steps.every((step) => step.done)).toBe(true)
    expect(view.doneCount).toBe(8)
    expect(view.currentStep).toBeNull()
  })

  // SPEC-060 · AC-23 (mitad derivada del retroceso: sin datos que lo sostengan,
  // el paso vuelve a estar pendiente — el paso NUNCA se persiste)
  it('walks back to step 4 when the company that sustained steps 4 and 5 disappears', () => {
    const before = derive(
      { ...ALL_DONE, hasInterviewGroup: false, hasGroupedInterview: false },
      { anthropicConfigured: true, deepgramConfigured: true }
    )
    expect(before.currentStep).toBe(7)

    const after = derive(
      {
        ...ALL_DONE,
        hasCompany: false,
        hasContact: false,
        firstCompanyId: null,
        hasInterviewGroup: false,
        hasGroupedInterview: false
      },
      { anthropicConfigured: true, deepgramConfigured: true }
    )
    expect(after.currentStep).toBe(4)
    expect(after.steps[3].done).toBe(false)
    expect(after.steps[4].done).toBe(false)
    expect(after.steps[4].target).toBe('/companies')
  })
})
